<?php
declare(strict_types=1);
namespace App\Jobs\Meeting;
use App\Enums\UserStatus; use App\Models\User; use App\Notifications\MeetingCanceledNotification; use App\Services\Notifications\NotificationAttemptTracker; use App\Support\Notifications\MeetingCancellationSnapshot; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Notification; use Throwable;
final class MeetingCanceledMailNotificationJob implements ShouldQueue {use Dispatchable,Queueable,SerializesModels;use InteractsWithQueue;public int $tries=0;public function __construct(public readonly array $snapshot,public readonly string $recipientId){}public function backoff():array{return[60,300];}public function middleware():array{return[(new WithoutOverlapping('meeting-canceled-mail:'.$this->snapshot['meeting_id'].':'.$this->recipientId))->releaseAfter(10)->expireAfter(300)];}public function handle():void{$u=User::find($this->recipientId);if(!$u||$u->status!==UserStatus::InProgress)return;$count=app(NotificationAttemptTracker::class)->increment('meeting_canceled:'.$this->snapshot['meeting_id'],$this->recipientId,'mail');if($count>3){$this->fail(new \RuntimeException('notification delivery attempts exceeded'));return;}try{Notification::sendNow($u,new MeetingCanceledNotification(MeetingCancellationSnapshot::toMeeting($this->snapshot)),['mail']);}catch(Throwable $e){if($count>=3){$this->fail($e);return;}throw $e;}}}
